112	/// Refusal (10)'s sentence (VR-26), which the tool matches to know a clip
113	/// waits only for its analysis (VR-28, `AgentServer+Framing.swift`).
114	pub fn no_subjects(clip: u32) -> String {
115	    format!("clip {clip} has no subjects to follow; analyze it first")
116	}
117	
118	/// VR-50 (h): `cursor` on a media clip whose media has no cursor file.
119	pub fn no_cursor_file(clip: u32) -> String {
120	    format!(
121	        "clip {clip}'s media has no cursor file, so there is no cursor to follow; frame it with \
122	         subject, center, fit or keep"
123	    )
124	}
125	
126	/// VR-51: a following kind on a media clip whose media has a cursor file.
127	pub fn cursor_not_faces(clip: u32) -> String {
128	    format!(
129	        "clip {clip}'s media has a cursor file, so it follows the cursor, not faces; frame it \
130	         with cursor, center, fit or keep"
131	    )
132	}
