124	/// What a segment frames: a face (its index), or a pair (current, other).
125	#[derive(Debug, Clone, Copy, PartialEq)]
126	enum Label {
127	    Face(usize),
128	    Both(usize, usize),
129	}
130	
131	#[derive(Debug, Clone, Copy, PartialEq)]
132	struct Segment {
133	    from: Ticks,
134	    to: Ticks,
135	    label: Label,
136	}
137	
138	fn coalesced(segments: Vec<Segment>) -> Vec<Segment> {
139	    let mut out: Vec<Segment> = Vec::new();
140	    for s in segments {
141	        match out.last_mut() {
142	            Some(last) if last.label == s.label => last.to = s.to,
143	            _ => out.push(s),
144	        }
145	    }
146	    out
147	}
148	
149	/// VR-61 (e): the segments over `[0, duration)`; `faces[m]` is mic m's face
150	/// index, `fits` whether a pair fits the window over a span. `None` with no
151	/// turn inside the clip.
152	fn segments(
153	    duration: Ticks,
154	    turns: &[Turn],
155	    mics: &[u32],
156	    faces: &[usize],
157	    fits: impl Fn(usize, usize, Ticks, Ticks) -> bool,
158	) -> Option<Vec<Segment>> {
159	    let mut bounds: Vec<Ticks> = vec![0, duration];
160	    bounds.extend(
161	        turns
162	            .iter()
163	            .flat_map(|u| [u.from, u.to])
164	            .map(|t| t.clamp(0, duration)),
165	    );
166	    bounds.sort_unstable();
167	    bounds.dedup();
168	    let mut raw: Vec<(Ticks, Ticks, Option<Label>)> = Vec::new();
169	    let mut previous: Option<Label> = None;
170	    for w in bounds.windows(2) {
171	        let (a, b) = (w[0], w[1]);
172	        let active: Vec<usize> = (0..mics.len())
173	            .filter(|&m| covered(turns, mics[m], a))
174	            .map(|m| faces[m])
175	            .collect();
176	        let label = match active.as_slice() {
177	            [] => None,
178	            [f] => Some(Label::Face(*f)),
179	            _ => {
180	                let held = previous.map(|l| match l {
181	                    Label::Face(f) | Label::Both(f, _) => f,
182	                });
183	                let current = held.filter(|f| active.contains(f)).unwrap_or(active[0]);
184	                let other = *active.iter().find(|&&f| f != current).expect("two faces");
185	                Some(if fits(current, other, a, b) {
186	                    Label::Both(current, other)
187	                } else {
188	                    Label::Face(current)
189	                })
190	            }
191	        };
192	        if label.is_some() {
193	            previous = label;
194	        }
195	        raw.push((a, b, label.or(previous)));
196	    }
197	    let first = raw.iter().find_map(|r| r.2)?;
198	    let mut out = coalesced(
199	        raw.into_iter()
200	            .map(|(from, to, l)| Segment {
201	                from,
202	                to,
203	                label: l.unwrap_or(first),
204	            })
205	            .collect(),
206	    );
207	    // SW-22 (h)'s merge: the earliest short segment joins the one before
208	    // it, the first the one after, until none is short.
209	    while out.len() > 1 {
210	        let Some(i) = out.iter().position(|s| s.to - s.from < SPEAKER_HOLD) else {
211	            break;
212	        };
213	        if i > 0 {
214	            out[i - 1].to = out[i].to;
215	        } else {
216	            out[1].from = out[0].from;
217	        }
218	        out.remove(i);
219	        out = coalesced(out);
220	    }
221	    Some(out)
222	}
