1	//! `follow: speaker`'s match (road map "creator-jobs" VR6a, spec §11 VR-61
2	//! (a)–(d)), pure, beside `reframe_speaker.rs`, which plans and writes the
3	//! path: which face is whose microphone.
4	//!
5	//! - **Faces** (VR-61 (a)). `reframe_tracks.rs`'s tracks of the in-clip
6	//!   faces (`link`, reused), chained across a gap when a later track starts
7	//!   after a chain's last box and overlaps it ([`LINK_IOU`], `iou`); a chain
8	//!   in at least [`FACE_SHARE`] of the samples is a face, at most
9	//!   [`MAX_SPEAKERS`] of them by sample count, numbered 1… left to right by
10	//!   median centre x (ties: the earlier first sample).
11	//! - **Activity** (b): a face's mouth's population standard deviation over
12	//!   ±[`ACTIVITY_SPAN`], at least two values.
13	//! - **Agreement** (c): Pearson's r between the activity and "a turn of the
14	//!   microphone covers the sample"; 0 when undefined.
15	//! - **Assignment** (d): the injective microphones → faces map with the
16	//!   greatest sum, ties to the smallest face list; [`sure`] when every pair
17	//!   reaches [`SPEAKER_AGREEMENT`], provisional until S-PC3 (VR-62).
18	//!
19	//! - **Across the FFI** (VR-65): [`clip_turns`] (the turns of a clip, in
20	//!   its ticks) and [`clip_speaker_match`], what `rc_project_speaker_match`
21	//!   answers, so Make Vertical's sheet shows the core's own match.
22	//!
23	//! All times are CLIP ticks, but for [`clip_speaker_match`]'s arguments.
24	
25	use crate::model::{Clip, Project};
26	use crate::reframe::in_clip_time;
27	use crate::reframe_subjects::{Subjects, Turn};
28	use crate::reframe_tracks::{
29	    centre, iou, link, median, SubjectBox, SubjectKind, SubjectSample, LINK_IOU,
30	};
31	use crate::time::{Ticks, TIMESCALE};
32	
33	/// A face's activity reads its mouths within this of a sample: ±0.25 s,
34	/// SW-81's 0.5 s window.
35	pub const ACTIVITY_SPAN: Ticks = TIMESCALE / 4;
36	/// The share of the samples a chain must be in to be a face.
37	pub const FACE_SHARE: f64 = 0.25;
38	/// The most faces a match considers.
39	pub const MAX_SPEAKERS: usize = 4;
40	/// The least agreement each assigned pair needs for the match to be sure;
41	/// PROVISIONAL until S-PC3 measures it (VR-62).
42	pub const SPEAKER_AGREEMENT: f64 = 0.2;
43	
44	/// One face found: its number (1… left to right), its median centre x
45	/// (0…1 of the picture) and how many samples it is in.
46	#[derive(Debug, Clone, Copy, PartialEq)]
47	pub struct SpeakerFace {
48	    pub face: u32,
49	    pub x: f64,
50	    pub samples: usize,
51	}
52	
53	/// The faces, each microphone's agreement with each face (`[mic][face]`),
54	/// the face number per microphone and whether the match is sure.
55	#[derive(Debug, Clone, PartialEq)]
56	pub struct SpeakerMatch {
57	    pub faces: Vec<SpeakerFace>,
58	    pub agreement: Vec<Vec<f64>>,
59	    pub assignment: Vec<u32>,
60	    pub sure: bool,
61	}
62	
63	/// A face's boxes by sample index, ascending.
64	pub(crate) struct FaceBoxes {
65	    first: usize,
66	    pub(crate) boxes: Vec<(usize, SubjectBox)>,
67	}
68	
69	impl FaceBoxes {
70	    pub(crate) fn at(&self, i: usize) -> Option<SubjectBox> {
71	        self.boxes
72	            .binary_search_by_key(&i, |b| b.0)
73	            .ok()
74	            .map(|n| self.boxes[n].1)
75	    }
76	}
77	
78	/// VR-61 (a): the faces, numbered left to right (index = number − 1).
79	pub(crate) fn faces_of(samples: &[SubjectSample]) -> Vec<FaceBoxes> {
80	    let shot = vec![0usize; samples.len()];
81	    let (tracks, _) = link(samples, &shot, &[SubjectKind::Face]);
82	    let mut order: Vec<usize> = (0..tracks.len()).collect();
83	    order.sort_by_key(|&n| (tracks[n].boxes[0].0, tracks[n].id));
84	    let mut chains: Vec<FaceBoxes> = Vec::new();
85	    for n in order {
86	        let (start, first_box) = tracks[n].boxes[0];
87	        let mut best: Option<(usize, f64)> = None;
88	        for (c, chain) in chains.iter().enumerate() {
89	            let (last, last_box) = *chain.boxes.last().expect("a chain has a box");
90	            let overlap = iou(&last_box, &first_box);
91	            if last < start && overlap >= LINK_IOU && best.is_none_or(|(_, o)| overlap > o) {
92	                best = Some((c, overlap));
93	            }
94	        }
95	        match best {
96	            Some((c, _)) => chains[c].boxes.extend(tracks[n].boxes.iter().copied()),
97	            None => chains.push(FaceBoxes {
98	                first: start,
99	                boxes: tracks[n].boxes.clone(),
100	            }),
101	        }
102	    }
103	    let least = FACE_SHARE * samples.len() as f64;
104	    chains.retain(|c| c.boxes.len() as f64 >= least);
105	    chains.sort_by_key(|c| (std::cmp::Reverse(c.boxes.len()), c.first));
106	    chains.truncate(MAX_SPEAKERS);
107	    let mut keyed: Vec<(f64, FaceBoxes)> = chains
108	        .into_iter()
109	        .map(|c| {
110	            let mut xs: Vec<f64> = c.boxes.iter().map(|(_, b)| centre(b).0).collect();
111	            (median(&mut xs), c)
112	        })
113	        .collect();
114	    keyed.sort_by(|a, b| a.0.total_cmp(&b.0).then(a.1.first.cmp(&b.1.first)));
115	    keyed.into_iter().map(|(_, c)| c).collect()
116	}
117	
118	/// VR-61 (b): per box, the population standard deviation of the face's
119	/// mouths within ±[`ACTIVITY_SPAN`] of its sample; `None` under two values.
120	/// The boxes ascend by sample and the samples by `t` (`reframe.rs` sorts
121	/// them), so each window is two indices that only move forward: the cost is
122	/// the boxes times a window's boxes (about five at 10 Hz), not the boxes
123	/// squared. Each window's values are summed in box order, two passes, so a
124	/// still mouth's deviation is exactly 0.
125	fn activities(face: &FaceBoxes, samples: &[SubjectSample]) -> Vec<(usize, Option<f64>)> {
126	    let times: Vec<Ticks> = face.boxes.iter().map(|&(i, _)| samples[i].t).collect();
127	    let (mut lo, mut hi) = (0usize, 0usize);
128	    let mut values: Vec<f64> = Vec::new();
129	    face.boxes
130	        .iter()
131	        .zip(&times)
132	        .map(|(&(i, _), &t)| {
133	            while times[lo] < t - ACTIVITY_SPAN {
134	                lo += 1;
135	            }
136	            while hi < times.len() && times[hi] <= t + ACTIVITY_SPAN {
137	                hi += 1;
138	            }
139	            values.clear();
140	            values.extend(face.boxes[lo..hi].iter().filter_map(|(_, b)| b.mouth));
141	            if values.len() < 2 {
142	                return (i, None);
143	            }
144	            let n = values.len() as f64;
145	            let mean = values.iter().sum::<f64>() / n;
146	            let variance = values.iter().map(|v| (v - mean).powi(2)).sum::<f64>() / n;
147	            (i, Some(variance.sqrt()))
148	        })
149	        .collect()
150	}
151	
152	/// Pearson's r of the pairs; 0 when it is undefined (VR-61 (c)).
153	pub fn pearson(pairs: &[(f64, f64)]) -> f64 {
154	    let n = pairs.len() as f64;
155	    if pairs.len() < 2 {
156	        return 0.0;
157	    }
158	    let (mx, my) = (
159	        pairs.iter().map(|p| p.0).sum::<f64>() / n,
160	        pairs.iter().map(|p| p.1).sum::<f64>() / n,
161	    );
162	    let (mut sxy, mut sxx, mut syy) = (0.0, 0.0, 0.0);
163	    for &(x, y) in pairs {
164	        sxy += (x - mx) * (y - my);
165	        sxx += (x - mx).powi(2);
166	        syy += (y - my).powi(2);
167	    }
168	    let r = sxy / (sxx * syy).sqrt();
169	    if r.is_finite() {
170	        r
171	    } else {
172	        0.0
173	    }
174	}
175	
176	/// Whether a match is sure: every assigned agreement at least
177	/// [`SPEAKER_AGREEMENT`] (VR-61 (d)).
178	pub fn sure(agreements: &[f64]) -> bool {
179	    agreements.iter().all(|&a| a >= SPEAKER_AGREEMENT)
180	}
181	
182	pub(crate) fn covered(turns: &[Turn], mic: u32, t: Ticks) -> bool {
183	    turns
184	        .iter()
185	        .any(|u| u.mic == mic && u.from <= t && t < u.to)
186	}
187	
188	/// [`covered`] at each of `times`, ascending, in one forward walk over
189	/// `own` — one microphone's turns as `(from, to)`, sorted: a time is covered
190	/// exactly when the latest end of the turns begun by it is after it.
191	fn coverage(own: &[(Ticks, Ticks)], times: impl Iterator<Item = Ticks>) -> Vec<bool> {
192	    let (mut next, mut reach) = (0usize, Ticks::MIN);
193	    times
194	        .map(|t| {
195	            while next < own.len() && own[next].0 <= t {
196	                reach = reach.max(own[next].1);
197	                next += 1;
198	            }
199	            t < reach
200	        })
201	        .collect()
202	}
203	
204	pub(crate) fn matched(
205	    samples: &[SubjectSample],
206	    faces: &[FaceBoxes],
207	    turns: &[Turn],
208	    mics: &[u32],
209	) -> Option<SpeakerMatch> {
210	    if faces.len() < mics.len() {
211	        return None;
212	    }
213	    let acts: Vec<Vec<(usize, Option<f64>)>> =
214	        faces.iter().map(|f| activities(f, samples)).collect();
215	    let agreement: Vec<Vec<f64>> = mics
216	        .iter()
217	        .map(|&mic| {
218	            let mut own: Vec<(Ticks, Ticks)> = turns
219	                .iter()
220	                .filter(|u| u.mic == mic)
221	                .map(|u| (u.from, u.to))
222	                .collect();
223	            own.sort_unstable();
224	            acts.iter()
225	                .map(|a| {
226	                    let cover = coverage(&own, a.iter().map(|&(i, _)| samples[i].t));
227	                    let pairs: Vec<(f64, f64)> = a
228	                        .iter()
229	                        .zip(cover)
230	                        .filter_map(|(&(_, v), c)| v.map(|v| (v, f64::from(u8::from(c)))))
231	                        .collect();
232	                    pearson(&pairs)
233	                })
234	                .collect()
235	        })
236	        .collect();
237	    // Every injective map in lexicographic order; a strictly greater sum
238	    // replaces the best, so a tie keeps the smallest face list.
239	    let mut best: Option<(f64, Vec<usize>)> = None;
240	    let mut chosen: Vec<usize> = Vec::new();
241	    fn walk(
242	        agreement: &[Vec<f64>],
243	        faces: usize,
244	        chosen: &mut Vec<usize>,
245	        best: &mut Option<(f64, Vec<usize>)>,
246	    ) {
247	        if chosen.len() == agreement.len() {
248	            let sum: f64 = chosen
249	                .iter()
250	                .enumerate()
251	                .map(|(m, &f)| agreement[m][f])
252	                .sum();
253	            if best.as_ref().is_none_or(|(b, _)| sum > *b) {
254	                *best = Some((sum, chosen.clone()));
255	            }
256	            return;
257	        }
258	        for f in 0..faces {
259	            if !chosen.contains(&f) {
260	                chosen.push(f);
261	                walk(agreement, faces, chosen, best);
262	                chosen.pop();
263	            }
264	        }
265	    }
266	    walk(&agreement, faces.len(), &mut chosen, &mut best);
267	    let (_, list) = best?;
268	    let assigned: Vec<f64> = list
269	        .iter()
270	        .enumerate()
271	        .map(|(m, &f)| agreement[m][f])
272	        .collect();
273	    Some(SpeakerMatch {
274	        faces: faces
275	            .iter()
276	            .enumerate()
277	            .map(|(n, f)| {
278	                let mut xs: Vec<f64> = f.boxes.iter().map(|(_, b)| centre(b).0).collect();
279	                SpeakerFace {
280	                    face: n as u32 + 1,
281	                    x: median(&mut xs),
282	                    samples: f.boxes.len(),
283	                }
284	            })
285	            .collect(),
286	        agreement,
287	        assignment: list.iter().map(|&f| f as u32 + 1).collect(),
288	        sure: sure(&assigned),
289	    })
290	}
291	
292	/// VR-61 (a)–(d) over samples and turns in CLIP ticks; `None` when fewer
293	/// faces are found than there are microphones. The samples must ascend by
294	/// `t`, as `reframe.rs`'s `in_clip_time` leaves them: each face's activity
295	/// window only moves forward.
296	pub fn speaker_match(
297	    samples: &[SubjectSample],
298	    turns: &[Turn],
299	    mics: &[u32],
300	) -> Option<SpeakerMatch> {
301	    matched(samples, &faces_of(samples), turns, mics)
302	}
303	
304	/// The turns of `clip`, from container timeline ticks to its own: each
305	/// clamped to `[0, duration]`, an empty one dropped (VR-61 (e)'s input).
306	pub(crate) fn clip_turns(clip: &Clip, turns: &[Turn]) -> Vec<Turn> {
307	    turns
308	        .iter()
309	        .map(|u| Turn {
310	            from: (u.from - clip.start).clamp(0, clip.duration),
311	            to: (u.to - clip.start).clamp(0, clip.duration),
312	            mic: u.mic,
313	        })
314	        .filter(|u| u.from < u.to)
315	        .collect()
316	}
317	
318	/// The match `follow: speaker` would make on `clip` (VR-65): `subjects` as
319	/// `reframe_clip` takes them (media source ticks, turns in timeline ticks)
320	/// through `in_clip_time` and [`clip_turns`], then the faces and
321	/// [`matched`]; `None` when fewer faces are found than there are
322	/// microphones.
323	pub fn clip_speaker_match(
324	    project: &Project,
325	    clip: &Clip,
326	    subjects: &Subjects,
327	    mics: &[u32],
328	) -> Option<SpeakerMatch> {
329	    let (samples, _) = in_clip_time(clip, project, subjects);
330	    let turns = clip_turns(clip, &subjects.turns);
331	    matched(&samples, &faces_of(&samples), &turns, mics)
332	}
333	
334	/// The median box of a face over the samples in `[a, b)`, else over all.
335	pub(crate) fn median_box(
336	    face: &FaceBoxes,
337	    samples: &[SubjectSample],
338	    a: Ticks,
339	    b: Ticks,
340	) -> SubjectBox {
341	    let inside: Vec<SubjectBox> = face
342	        .boxes
343	        .iter()
344	        .filter(|(i, _)| (a..b).contains(&samples[*i].t))
345	        .map(|&(_, b)| b)
346	        .collect();
347	    let list = if inside.is_empty() {
348	        face.boxes.iter().map(|&(_, b)| b).collect()
349	    } else {
350	        inside
351	    };
352	    let of = |f: fn(&SubjectBox) -> f64| median(&mut list.iter().map(f).collect::<Vec<_>>());
353	    SubjectBox {
354	        x: of(|b| b.x),
355	        y: of(|b| b.y),
356	        w: of(|b| b.w),
357	        h: of(|b| b.h),
358	        c: of(|b| b.c),
359	        mouth: None,
360	    }
361	}
