155	/// The keys of one clip's path (spec §11 VR-23, VR-24): `chosen` one per
156	/// sample in clip ticks, `shots` the cuts in clip ticks (`Round::Up`).
157	pub(crate) fn write_keys(
158	    frame: &Frame,
159	    chosen: &[Chosen],
160	    shots: &[Ticks],
161	    duration: Ticks,
162	    fps: Fps,
163	    request: &FramingRequest,
164	    tuning: &FramingTuning,
165	) -> FramingPath {
166	    let shot = |t: Ticks| shots.partition_point(|&c| c <= t);
167	    let (ww, wh) = frame.window;
168	    let one = one_frame(fps);
169	    // Each kept cut: its shot's clip tick and its key time `c`, the first
170	    // canvas frame that shows the new shot (VR-24 (a)).
171	    let mut cuts: Vec<(Ticks, Ticks)> = shots
172	        .iter()
173	        .map(|&s| (s, snap_up_to_frame(s, fps)))
174	        .filter(|&(_, c)| c > one && c < duration)
175	        .collect();
176	    cuts.dedup_by_key(|&mut (_, c)| c);
177	    let empty_state = match request.where_empty {
178	        WhereEmpty::Center => At::Window(frame.centre()),
179	        WhereEmpty::Fit => At::Fit,
180	    };
181	
182	    // Each chosen sample's kind, subject point and offset (VR-22, VR-24 (g)).
183	    let points: Vec<Option<(SubjectKind, Point, Point)>> = chosen
184	        .iter()
185	        .map(|c| point_of(frame, c, tuning.headroom))
186	        .collect();
187	    // The median over ±0.5 s of the same kind in the same shot, then the
188	    // desired window centre, clamped (VR-23).
189	    let filtered: Vec<Option<(Point, Point)>> = (0..chosen.len())
190	        .map(|i| {
191	            let (kind, _, offset) = points[i]?;
192	            let t = chosen[i].t;
193	            let lo = chosen.partition_point(|q| q.t < t - MEDIAN_SPAN);
194	            let hi = chosen.partition_point(|q| q.t <= t + MEDIAN_SPAN);
195	            let near: Vec<Point> = (lo..hi)
196	                .filter_map(|j| points[j].filter(|q| q.0 == kind).map(|q| (j, q.1)))
197	                .filter(|&(j, _)| shot(chosen[j].t) == shot(t))
198	                .map(|(_, p)| p)
199	                .collect();
200	            let mut xs: Vec<f64> = near.iter().map(|p| p.0).collect();
201	            let mut ys: Vec<f64> = near.iter().map(|p| p.1).collect();
202	            let fp = (median(&mut xs), median(&mut ys));
203	            Some((fp, frame.clamp((fp.0 + offset.0, fp.1 + offset.1))))
204	        })
205	        .collect();
206	
207	    // The first key (VR-24 (f)): the first chosen sample's desired centre
208	    // when one is chosen within `LOSS_HOLD` in the first shot, else EMPTY.
209	    let first_cut = cuts.first().map_or(Ticks::MAX, |&(s, _)| s);
210	    let first = (0..chosen.len()).find(|&i| filtered[i].is_some());
211	    let (start_at, mut following) = match first {
212	        Some(i) if chosen[i].t < LOSS_HOLD && chosen[i].t < first_cut => (
213	            At::Window(filtered[i].expect("chosen").1),
214	            chosen[i].identity,
215	        ),
216	        _ => (empty_state, None),
217	    };
218	    let mut empty = start_at == empty_state && following.is_none();
219	    let mut w = Writer {
220	        frame,
221	        keys: Vec::new(),
222	        current: start_at,
223	        shows_fit: start_at == At::Fit,
224	        last_end: None,
225	    };
226	    w.keys.push(w.key(0, start_at, Curve::Linear));
227	    let mut cut_keys: Vec<Ticks> = Vec::new();
228	
229	    let mut loss: Option<Ticks> = None;
230	    let mut seen: Option<Ticks> = None;
231	    let mut next = 0usize;
232	    // The frame before a cut's, and the latest a move or an ease may end:
233	    // the frame before the next cut.
234	    let before = |c: Ticks| snap_down_to_frame(c - 1, fps);
235	    let limit = |next: usize| cuts.get(next).map_or(duration, |&(_, c)| before(c));
236	    let mut i = 0usize;
237	    while i <= chosen.len() {
238	        let t = chosen.get(i).map_or(Ticks::MAX, |c| c.t);
239	        // Each cut at or before this sample, in order (VR-24 (b)).
240	        while next < cuts.len() && cuts[next].0 <= t {
241	            let (s, c) = cuts[next];
242	            let in_shot: Vec<usize> = (0..chosen.len())
243	                .filter(|&j| shot(chosen[j].t) == shot(s) && chosen[j].t < c + CUT_MEDIAN)
244	                .collect();
245	            let lead = in_shot.iter().copied().find(|&j| points[j].is_some());
246	            let to = match lead {
247	                Some(l) => {
248	                    let (kind, _, offset) = points[l].expect("chosen");
249	                    let same: Vec<Point> = in_shot
250	                        .iter()
251	                        .filter(|&&j| chosen[j].identity == chosen[l].identity)
252	                        .filter_map(|&j| points[j].filter(|q| q.0 == kind).map(|q| q.1))
253	                        .collect();
254	                    let mut xs: Vec<f64> = same.iter().map(|p| p.0).collect();
255	                    let mut ys: Vec<f64> = same.iter().map(|p| p.1).collect();
256	                    let m = (median(&mut xs), median(&mut ys));
257	                    At::Window(frame.clamp((m.0 + offset.0, m.1 + offset.1)))
258	                }
259	                None => empty_state,
260	            };
261	            if to != w.current {
262	                w.go(before(c), c, to, Curve::Linear);
263	                cut_keys.push(c);
264	            }
265	            w.last_end = Some(c);
266	            empty = lead.is_none();
267	            following = lead.and_then(|l| chosen[l].identity);
268	            loss = None;
269	            seen = None;
270	            next += 1;
271	        }
272	        let Some(c) = chosen.get(i) else { break };
273	        i += 1;
274	        let has = filtered[i - 1];
275	        if empty {
276	            // Return from EMPTY (VR-24 (e)).
277	            if has.is_none() {
278	                seen = None;
279	                continue;
280	            }
281	            let since = *seen.get_or_insert(t);
282	            if t - since < RETURN_SEEN || w.running(t) {
283	                continue;
284	            }
285	            let desired = has.expect("chosen").1;
286	            let centre = frame.centre();
287	            let distance = (desired.0 - centre.0).hypot(desired.1 - centre.1);
288	            let seconds = MOVE_MIN.max(distance / (tuning.speed * ww));
289	            if let Some((start, end)) = span(t, seconds, duration, fps) {
290	                if end <= limit(next) {
291	                    w.go(start, end, At::Window(desired), Curve::EaseInOut);
292	                    empty = false;
293	                    following = c.identity;
294	                    seen = None;
295	                    loss = None;
296	                }
297	            }
298	            continue;
299	        }
300	        // Loss (VR-24 (d)).
301	        match loss {
302	            None if has.is_none() || (c.lost && c.identity != following) => {
303	                loss = Some(t);
304	                continue;
305	            }
306	            None => {}
307	            Some(t0) => {
308	                if has.is_some() && !c.lost && c.identity == following {
309	                    loss = None;
310	                } else if t - t0 < LOSS_HOLD {
311	                    continue;
312	                } else if has.is_some() {
313	                    loss = None;
314	                } else {
315	                    if !w.running(t) {
316	                        let seconds = EMPTY_EASE as f64 / TIMESCALE as f64;
317	                        if let Some((start, end)) = span(t, seconds, duration, fps) {
318	                            if end <= limit(next) {
319	                                w.go(start, end, empty_state, Curve::EaseInOut);
320	                                empty = true;
321	                                loss = None;
322	                                seen = None;
323	                                following = None;
324	                            }
325	                        }
326	                    }
327	                    continue;
328	                }
329	            }
330	        }
331	        following = c.identity;
332	        // VR-23's move.
333	        let (fp, desired) = has.expect("chosen");
334	        let At::Window(current) = w.current else {
335	            continue;
336	        };
337	        if w.running(t) {
338	            continue;
339	        }
340	        let (dx, dy) = (desired.0 - current.0, desired.1 - current.1);
341	        if dx.abs() <= tuning.dead_zone_width * ww && dy.abs() <= tuning.dead_zone_height * wh {
342	            continue;
343	        }
344	        let outside = (fp.0 - current.0).abs() > ww / 2.0 || (fp.1 - current.1).abs() > wh / 2.0;
345	        if w.last_end.is_some_and(|end| t < end + MOVE_SPACING) && !outside {
346	            continue;
347	        }
348	        let seconds = MOVE_MIN.max(dx.hypot(dy) / (tuning.speed * ww));
349	        if let Some((start, end)) = span(t, seconds, duration, fps) {
350	            if end <= limit(next) {
351	                w.go(start, end, At::Window(desired), Curve::EaseInOut);
352	            }
353	        }
354	    }
355	    FramingPath {
356	        keys: w.keys,
357	        shows_fit: w.shows_fit,
358	        cuts: cut_keys,
359	    }
360	}
361	
362	/// A move of `seconds` from sample `t`, snapped (VR-23): at least a frame,
363	/// and `None` when it would end past the clip.
364	pub(crate) fn span(t: Ticks, seconds: f64, duration: Ticks, fps: Fps) -> Option<(Ticks, Ticks)> {
365	    let length = (seconds * TIMESCALE as f64).min((duration as f64) * 2.0 + 1.0);
366	    let start = snap_to_frame(t, fps);
367	    let mut end = snap_to_frame(t.saturating_add(length.round() as Ticks), fps);
368	    if end <= start {
369	        end = snap_up_to_frame(start + 1, fps);
370	    }
371	    (end <= duration).then_some((start, end))
372	}
