33	/// A face's activity reads its mouths within this of a sample: ±0.25 s,
34	/// SW-81's 0.5 s window.
35	pub const ACTIVITY_SPAN: Ticks = TIMESCALE / 4;
36	/// The share of the samples a chain must be in to be a face.
37	pub const FACE_SHARE: f64 = 0.25;
38	/// The most faces a match considers.
39	pub const MAX_SPEAKERS: usize = 4;
40	/// The least agreement each assigned pair needs for the match to be sure;
41	/// PROVISIONAL until S-PC3 measures it (VR-62).
42	pub const SPEAKER_AGREEMENT: f64 = 0.2;
