44	/// One face found: its number (1… left to right), its median centre x
45	/// (0…1 of the picture) and how many samples it is in.
46	#[derive(Debug, Clone, Copy, PartialEq)]
47	pub struct SpeakerFace {
48	    pub face: u32,
49	    pub x: f64,
50	    pub samples: usize,
51	}
