78	/// VR-61 (a): the faces, numbered left to right (index = number − 1).
79	pub(crate) fn faces_of(samples: &[SubjectSample]) -> Vec<FaceBoxes> {
80	    let shot = vec![0usize; samples.len()];
81	    let (tracks, _) = link(samples, &shot, &[SubjectKind::Face]);
82	    let mut order: Vec<usize> = (0..tracks.len()).collect();
83	    order.sort_by_key(|&n| (tracks[n].boxes[0].0, tracks[n].id));
84	    let mut chains: Vec<FaceBoxes> = Vec::new();
85	    for n in order {
86	        let (start, first_box) = tracks[n].boxes[0];
87	        let mut best: Option<(usize, f64)> = None;
88	        for (c, chain) in chains.iter().enumerate() {
89	            let (last, last_box) = *chain.boxes.last().expect("a chain has a box");
90	            let overlap = iou(&last_box, &first_box);
91	            if last < start && overlap >= LINK_IOU && best.is_none_or(|(_, o)| overlap > o) {
92	                best = Some((c, overlap));
93	            }
94	        }
95	        match best {
96	            Some((c, _)) => chains[c].boxes.extend(tracks[n].boxes.iter().copied()),
97	            None => chains.push(FaceBoxes {
98	                first: start,
99	                boxes: tracks[n].boxes.clone(),
100	            }),
101	        }
102	    }
103	    let least = FACE_SHARE * samples.len() as f64;
104	    chains.retain(|c| c.boxes.len() as f64 >= least);
105	    chains.sort_by_key(|c| (std::cmp::Reverse(c.boxes.len()), c.first));
106	    chains.truncate(MAX_SPEAKERS);
107	    let mut keyed: Vec<(f64, FaceBoxes)> = chains
108	        .into_iter()
109	        .map(|c| {
110	            let mut xs: Vec<f64> = c.boxes.iter().map(|(_, b)| centre(b).0).collect();
111	            (median(&mut xs), c)
112	        })
113	        .collect();
114	    keyed.sort_by(|a, b| a.0.total_cmp(&b.0).then(a.1.first.cmp(&b.1.first)));
115	    keyed.into_iter().map(|(_, c)| c).collect()
116	}
117	
118	/// VR-61 (b): per box, the population standard deviation of the face's
119	/// mouths within ±[`ACTIVITY_SPAN`] of its sample; `None` under two values.
120	/// The boxes ascend by sample and the samples by `t` (`reframe.rs` sorts
121	/// them), so each window is two indices that only move forward: the cost is
122	/// the boxes times a window's boxes (about five at 10 Hz), not the boxes
123	/// squared. Each window's values are summed in box order, two passes, so a
124	/// still mouth's deviation is exactly 0.
125	fn activities(face: &FaceBoxes, samples: &[SubjectSample]) -> Vec<(usize, Option<f64>)> {
126	    let times: Vec<Ticks> = face.boxes.iter().map(|&(i, _)| samples[i].t).collect();
127	    let (mut lo, mut hi) = (0usize, 0usize);
128	    let mut values: Vec<f64> = Vec::new();
129	    face.boxes
130	        .iter()
131	        .zip(&times)
132	        .map(|(&(i, _), &t)| {
133	            while times[lo] < t - ACTIVITY_SPAN {
134	                lo += 1;
135	            }
136	            while hi < times.len() && times[hi] <= t + ACTIVITY_SPAN {
137	                hi += 1;
138	            }
139	            values.clear();
140	            values.extend(face.boxes[lo..hi].iter().filter_map(|(_, b)| b.mouth));
141	            if values.len() < 2 {
142	                return (i, None);
143	            }
144	            let n = values.len() as f64;
145	            let mean = values.iter().sum::<f64>() / n;
146	            let variance = values.iter().map(|v| (v - mean).powi(2)).sum::<f64>() / n;
147	            (i, Some(variance.sqrt()))
148	        })
149	        .collect()
150	}
151	
152	/// Pearson's r of the pairs; 0 when it is undefined (VR-61 (c)).
153	pub fn pearson(pairs: &[(f64, f64)]) -> f64 {
154	    let n = pairs.len() as f64;
155	    if pairs.len() < 2 {
156	        return 0.0;
157	    }
158	    let (mx, my) = (
159	        pairs.iter().map(|p| p.0).sum::<f64>() / n,
160	        pairs.iter().map(|p| p.1).sum::<f64>() / n,
161	    );
162	    let (mut sxy, mut sxx, mut syy) = (0.0, 0.0, 0.0);
163	    for &(x, y) in pairs {
164	        sxy += (x - mx) * (y - my);
165	        sxx += (x - mx).powi(2);
166	        syy += (y - my).powi(2);
167	    }
168	    let r = sxy / (sxx * syy).sqrt();
169	    if r.is_finite() {
170	        r
171	    } else {
172	        0.0
173	    }
174	}
