176	/// Whether a match is sure: every assigned agreement at least
177	/// [`SPEAKER_AGREEMENT`] (VR-61 (d)).
178	pub fn sure(agreements: &[f64]) -> bool {
179	    agreements.iter().all(|&a| a >= SPEAKER_AGREEMENT)
180	}
