182	pub(crate) fn covered(turns: &[Turn], mic: u32, t: Ticks) -> bool {
183	    turns
184	        .iter()
185	        .any(|u| u.mic == mic && u.from <= t && t < u.to)
186	}
187	
188	/// [`covered`] at each of `times`, ascending, in one forward walk over
189	/// `own` — one microphone's turns as `(from, to)`, sorted: a time is covered
190	/// exactly when the latest end of the turns begun by it is after it.
191	fn coverage(own: &[(Ticks, Ticks)], times: impl Iterator<Item = Ticks>) -> Vec<bool> {
192	    let (mut next, mut reach) = (0usize, Ticks::MIN);
193	    times
194	        .map(|t| {
195	            while next < own.len() && own[next].0 <= t {
196	                reach = reach.max(own[next].1);
197	                next += 1;
198	            }
199	            t < reach
200	        })
201	        .collect()
202	}
