204	pub(crate) fn matched(
205	    samples: &[SubjectSample],
206	    faces: &[FaceBoxes],
207	    turns: &[Turn],
208	    mics: &[u32],
209	) -> Option<SpeakerMatch> {
210	    if faces.len() < mics.len() {
211	        return None;
212	    }
213	    let acts: Vec<Vec<(usize, Option<f64>)>> =
214	        faces.iter().map(|f| activities(f, samples)).collect();
215	    let agreement: Vec<Vec<f64>> = mics
216	        .iter()
217	        .map(|&mic| {
218	            let mut own: Vec<(Ticks, Ticks)> = turns
219	                .iter()
220	                .filter(|u| u.mic == mic)
221	                .map(|u| (u.from, u.to))
222	                .collect();
223	            own.sort_unstable();
224	            acts.iter()
225	                .map(|a| {
226	                    let cover = coverage(&own, a.iter().map(|&(i, _)| samples[i].t));
227	                    let pairs: Vec<(f64, f64)> = a
228	                        .iter()
229	                        .zip(cover)
230	                        .filter_map(|(&(_, v), c)| v.map(|v| (v, f64::from(u8::from(c)))))
231	                        .collect();
232	                    pearson(&pairs)
233	                })
234	                .collect()
235	        })
236	        .collect();
237	    // Every injective map in lexicographic order; a strictly greater sum
238	    // replaces the best, so a tie keeps the smallest face list.
239	    let mut best: Option<(f64, Vec<usize>)> = None;
240	    let mut chosen: Vec<usize> = Vec::new();
241	    fn walk(
242	        agreement: &[Vec<f64>],
243	        faces: usize,
244	        chosen: &mut Vec<usize>,
245	        best: &mut Option<(f64, Vec<usize>)>,
246	    ) {
247	        if chosen.len() == agreement.len() {
248	            let sum: f64 = chosen
249	                .iter()
250	                .enumerate()
251	                .map(|(m, &f)| agreement[m][f])
252	                .sum();
253	            if best.as_ref().is_none_or(|(b, _)| sum > *b) {
254	                *best = Some((sum, chosen.clone()));
255	            }
256	            return;
257	        }
258	        for f in 0..faces {
259	            if !chosen.contains(&f) {
260	                chosen.push(f);
261	                walk(agreement, faces, chosen, best);
262	                chosen.pop();
263	            }
264	        }
265	    }
266	    walk(&agreement, faces.len(), &mut chosen, &mut best);
267	    let (_, list) = best?;
268	    let assigned: Vec<f64> = list
269	        .iter()
270	        .enumerate()
271	        .map(|(m, &f)| agreement[m][f])
272	        .collect();
273	    Some(SpeakerMatch {
274	        faces: faces
275	            .iter()
276	            .enumerate()
277	            .map(|(n, f)| {
278	                let mut xs: Vec<f64> = f.boxes.iter().map(|(_, b)| centre(b).0).collect();
279	                SpeakerFace {
280	                    face: n as u32 + 1,
281	                    x: median(&mut xs),
282	                    samples: f.boxes.len(),
283	                }
284	            })
285	            .collect(),
286	        agreement,
287	        assignment: list.iter().map(|&f| f as u32 + 1).collect(),
288	        sure: sure(&assigned),
289	    })
290	}
