304	/// The turns of `clip`, from container timeline ticks to its own: each
305	/// clamped to `[0, duration]`, an empty one dropped (VR-61 (e)'s input).
306	pub(crate) fn clip_turns(clip: &Clip, turns: &[Turn]) -> Vec<Turn> {
307	    turns
308	        .iter()
309	        .map(|u| Turn {
310	            from: (u.from - clip.start).clamp(0, clip.duration),
311	            to: (u.to - clip.start).clamp(0, clip.duration),
312	            mic: u.mic,
313	        })
314	        .filter(|u| u.from < u.to)
