334	/// The median box of a face over the samples in `[a, b)`, else over all.
335	pub(crate) fn median_box(
336	    face: &FaceBoxes,
337	    samples: &[SubjectSample],
338	    a: Ticks,
339	    b: Ticks,
340	) -> SubjectBox {
341	    let inside: Vec<SubjectBox> = face
342	        .boxes
343	        .iter()
344	        .filter(|(i, _)| (a..b).contains(&samples[*i].t))
345	        .map(|&(_, b)| b)
346	        .collect();
347	    let list = if inside.is_empty() {
348	        face.boxes.iter().map(|&(_, b)| b).collect()
349	    } else {
350	        inside
351	    };
352	    let of = |f: fn(&SubjectBox) -> f64| median(&mut list.iter().map(f).collect::<Vec<_>>());
353	    SubjectBox {
354	        x: of(|b| b.x),
355	        y: of(|b| b.y),
356	        w: of(|b| b.w),
357	        h: of(|b| b.h),
358	        c: of(|b| b.c),
359	        mouth: None,
360	    }
361	}
