1	//! `reframe_clip {follow: "layout"}` — a camera and the screen behind it
2	//! re-laid on the current canvas (road map "creator-jobs" VR5b, spec §11
3	//! VR-53). Each switch Clip ▸ Camera Layout ▸ made is recognised on the
4	//! AUTHORED canvas (`from`, `layout_recognise.rs`) and solved again here by
5	//! `switch_layout`'s own composition (`compose_switch`), so a re-laid switch
6	//! is exactly the one a person would make on this canvas.
7	//!
8	//! - **The group.** Every top-level clip holding a layout action
9	//!   (`is_layout`) is laid out. A camera action at absolute T pairs with the
10	//!   layout action starting at T on the front-most track behind the
11	//!   camera's that holds one (CO-64's front and behind); a laid-out clip is
12	//!   a SCREEN when one on a track in front holds a layout action starting
13	//!   when one of its own does, else a CAMERA. The group is the closure over
14	//!   pairing from the given clip, plus each switch's PIECES: the clips of the
15	//!   same source (`same_source`, which ignores `in`) on a role's track
16	//!   starting after its action and before the track's next layout action,
17	//!   whose base is `alike` that action's end — the cut pieces of a laid-out
18	//!   recording, which CO-61's reach gave the layout as their base.
19	//! - **The replay.** Every group clip and piece takes `keep`'s per-axis
20	//!   rescale of its BASE (`rescale_video`); the group's layout actions are
21	//!   removed; the switches are composed again in time order at the camera
22	//!   action's absolute start, with [`switch_timing`]'s duration and curve,
23	//!   the recognised layout (Side by Side as Stacked on a canvas taller than
24	//!   wide) and its pieces as each role's later clips, nothing ending a
25	//!   reach. The focus is the old crop's centre (`focus_of`).
26	//! - **The other moves.** Each other moving end of a group clip or piece (a
27	//!   zoom) is re-based by [`conjugate`] from the placement in effect at its
28	//!   start on the old project to the one on the new, so what it zooms on
29	//!   keeps its place in the picture.
30	//!
31	//! Refused in VR-53 (c)'s order (`edit.rs`'s row); CO-62's refusals are not
32	//! asked again: each switch passed them when it was made.
33	
34	use std::collections::{BTreeSet, HashMap};
35	
36	use serde_json::{Map, Value};
37	
38	use crate::action_class::{is_layout, moves};
39	use crate::edit_canvas::rescale_video;
40	use crate::edit_layout_reach::{Role, RoleKind};
41	use crate::layout::{CameraLayout, LayoutChoice, Placement, DEFAULT_SWITCH};
42	use crate::layout_recognise::{alike, recognise, same_source};
43	use crate::model::{Action, Clip, Curve, Project};
44	use crate::outcome::Outcome;
45	use crate::props_check::{SCALE_MAX, SCALE_MIN};
46	use crate::time::Ticks;
47	
48	/// One layout action: its clip, its id and its absolute start.
49	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
50	struct Act {
51	    clip: u32,
52	    action: u32,
53	    at: Ticks,
54	}
55	
56	/// A recognised switch: the camera's action, the screen's paired one, the
57	/// layout, and each role's pieces.
58	struct Switch {
59	    camera: Act,
60	    screen: Option<Act>,
61	    choice: LayoutChoice,
62	    camera_pieces: Vec<u32>,
63	    screen_pieces: Vec<u32>,
64	}
65	
66	/// The duration and curve a switch is replayed with: those of its longest
67	/// role action that does not start at its clip's first frame (a cut there
68	/// is one frame long whatever the switch's length), else the camera
69	/// action's — `actions` holds the camera's first.
70	pub(crate) fn switch_timing(actions: &[(&Clip, &Action)]) -> (Ticks, Curve) {
71	    let mut chosen: Option<&Action> = None;
72	    for (_, action) in actions {
73	        if action.start != 0 && chosen.is_none_or(|c| action.duration > c.duration) {
74	            chosen = Some(action);
75	        }
76	    }
77	    match chosen.or(actions.first().map(|(_, a)| *a)) {
78	        Some(action) => (action.duration, action.curve),
79	        None => (DEFAULT_SWITCH, Curve::EaseInOut),
80	    }
81	}
82	
83	/// A moving end re-based from the placement `old` it was made over to
84	/// `new`: with `r = new.scale / old.scale`, each of `x`, `y` and `scale`
85	/// the end names is written `new.x + r·(x − old.x)`, `new.y + r·(y − old.y)`
86	/// and `scale·r` (clamped), so the picture point it shows at a canvas point
87	/// keeps its place relative to the layout's picture.
88	pub(crate) fn conjugate(end: &mut Map<String, Value>, old: &Placement, new: &Placement) {
89	    let r = new.scale / old.scale;
90	    if !(r.is_finite() && r > 0.0) {
91	        return;
92	    }
93	    let read = |end: &Map<String, Value>, key: &str| end.get(key).and_then(Value::as_f64);
94	    if let Some(x) = read(end, "x") {
95	        end.insert("x".into(), Value::from(new.x + r * (x - old.x)));
96	    }
97	    if let Some(y) = read(end, "y") {
98	        end.insert("y".into(), Value::from(new.y + r * (y - old.y)));
99	    }
100	    if let Some(scale) = read(end, "scale") {
101	        end.insert(
102	            "scale".into(),
103	            Value::from((scale * r).clamp(SCALE_MIN, SCALE_MAX)),
104	        );
105	    }
106	}
