1	//! `follow: cursor` — a screen recording framed on its recorded pointer
2	//! (road map "creator-jobs" VR5, spec §11 VR-50). Pure; `edit_reframe.rs`'s
3	//! op writes the path as it writes every framing (`reframe_compose.rs`).
4	//!
5	//! **The points.** `subjects.cursor` (`reframe_subjects.rs`), in forward-media
6	//! source ticks, is put into clip time by [`cursor_in_clip_time`]: kept in the
7	//! played window, mapped through `clip_source_time.rs`'s one mapping, one
8	//! point per clip tick with `click` and `typing` OR'ed over the points merged.
9	//!
10	//! **The window** is `reframe.rs`'s `Frame` at the request's zoom from the
11	//! current canvas: a point lands on the source canvas through the placement in
12	//! force (`Frame::point`, VR-27 (a)) and the desired centre is that point
13	//! clamped (`Frame::clamp`) — no headroom, no offset, since a pointer is a
14	//! point and not a head.
15	//!
16	//! **The moves** ([`CURSOR_TUNING`]): the first key on the first point; a
17	//! dead zone ±0.20 of the window's width and ±0.12 of its height around the
18	//! window's target, wider than a face's 0.15 because a pointer wanders where a
19	//! face holds still; a down click outside it ARRIVES — its move ends on the
20	//! click's frame, planned back from it at 0.8 window widths a second (at
21	//! least 0.4 s) and started no earlier than the last move's end; any other
22	//! point outside it starts VR-23's move unless one runs, it is within 0.5 s of
23	//! the last move's end with the pointer still in the window, the move would
24	//! end after a pending arrival's start, or the pointer is typing — a typing
25	//! stretch holds the window, where a click inside one still arrives. No cut,
26	//! no `fit`: `where_empty` and `backdrop` never act on it.
27	
28	use crate::clip_source_time::{clip_time_of_source, in_played_window, Round};
29	use crate::model::{Clip, Curve, MediaKind, Project, Source};
30	use crate::reframe::{
31	    Frame, FramingKey, FramingPath, FramingRequest, FramingTuning, Point, WhereEmpty,
32	};
33	use crate::reframe_path::{span, MOVE_MIN, MOVE_SPACING};
34	use crate::reframe_subjects::CursorPoint;
35	use crate::reframe_tracks::Follow;
36	use crate::time::{snap_to_frame, Fps, Ticks, TIMESCALE};
37	
38	/// VR-50 (d): the dead zone ±0.20 of the window's width (a face's is 0.15)
39	/// and ±0.12 of its height, 0.8 window widths a second, no headroom.
40	pub const CURSOR_TUNING: FramingTuning = FramingTuning {
41	    dead_zone_width: 0.20,
42	    dead_zone_height: 0.12,
43	    speed: 0.8,
44	    headroom: 0.0,
45	};
46	
47	/// VR-50 (a): the points in clip time — kept in the played window, mapped
48	/// with `Round::Down`, sorted by (clip tick, media tick), one per clip tick
49	/// (the earliest media tick's position) with `click` and `typing` OR'ed over
50	/// the points it stands for. Empty for a clip that is not a media clip.
51	pub(crate) fn cursor_in_clip_time(
52	    clip: &Clip,
53	    project: &Project,
54	    points: &[CursorPoint],
55	) -> Vec<CursorPoint> {
56	    let Source::Media { media, .. } = clip.source else {
57	        return Vec::new();
58	    };
59	    let Some(media) = project.media(media) else {
60	        return Vec::new();
61	    };
62	    let mut mapped: Vec<(Ticks, Ticks, CursorPoint)> = points
63	        .iter()
64	        .filter(|p| in_played_window(clip, media, p.t))
65	        .filter_map(|p| clip_time_of_source(clip, media, p.t, Round::Down).map(|c| (c, p.t, *p)))
66	        .collect();
67	    mapped.sort_by_key(|&(c, m, _)| (c, m));
68	    let mut out: Vec<CursorPoint> = Vec::with_capacity(mapped.len());
69	    for (c, _, p) in mapped {
70	        match out.last_mut() {
71	            Some(last) if last.t == c => {
72	                last.click |= p.click;
73	                last.typing |= p.typing;
74	            }
75	            _ => out.push(CursorPoint { t: c, ..p }),
76	        }
77	    }
78	    out
79	}
80	
81	/// The cursor's framing path (spec §11 VR-50). `None` for: no such clip, not
82	/// a media clip of a video media, a base rotation other than 0, a media with
83	/// no size, a crop or scale that leaves no picture, or a zoom outside 1…4 —
84	/// each refused by name before `reframe_clip` calls it. With no point in the
85	/// played window the path is one key on the picture's centre, which the op
86	/// refuses as "no subjects".
87	pub fn plan_cursor_framing(
88	    project: &Project,
89	    clip: u32,
90	    points: &[CursorPoint],
91	    zoom: f64,
92	) -> Option<FramingPath> {
93	    let clip = project.clip(clip)?;
94	    let Source::Media { media, .. } = clip.source else {
95	        return None;
96	    };
97	    let media = project.media(media)?;
98	    if media.kind != MediaKind::Video || !media.has_video {
99	        return None;
100	    }
101	    let request = FramingRequest {
102	        follow: Follow::Subject,
103	        zoom,
104	        from_width: project.canvas.width,
105	        from_height: project.canvas.height,
106	        where_empty: WhereEmpty::Fit,
107	    };
108	    let mut frame = Frame::of(project, clip, &request)?;
109	    let points = cursor_in_clip_time(clip, project, points);
110	    if !clip.actions.is_empty() {
111	        frame.placed = points
112	            .iter()
113	            .map(|p| {
114	                let v = project.evaluate_clip(clip, p.t).video;
115	                (p.t, v.scale, v.x, v.y)
116	            })
117	            .collect();
118	    }
119	    Some(write_cursor_keys(
120	        &frame,
121	        &points,
122	        clip.duration,
123	        project.canvas.fps,
124	        &CURSOR_TUNING,
125	    ))
126	}
127	
128	/// The keys (VR-50 (c)–(g)).
129	fn write_cursor_keys(
130	    frame: &Frame,
131	    points: &[CursorPoint],
132	    duration: Ticks,
133	    fps: Fps,
134	    tuning: &FramingTuning,
135	) -> FramingPath {
136	    let (ww, wh) = frame.window;
137	    let raw: Vec<Point> = points.iter().map(|p| frame.point(p.t, p.x, p.y)).collect();
138	    let desired: Vec<Point> = raw.iter().map(|&p| frame.clamp(p)).collect();
139	    let mut target = desired.first().copied().unwrap_or_else(|| frame.centre());
140	    let mut keys = vec![frame.key(0, target, Curve::Linear)];
141	    let mut last_end: Option<Ticks> = None;
142	    // A click whose arrival was dropped, or that is already reached, is
143	    // followed as any other point.
144	    let mut handled = 0usize;
145	    let outside = |target: Point, to: Point| {
146	        (to.0 - target.0).abs() > tuning.dead_zone_width * ww
147	            || (to.1 - target.1).abs() > tuning.dead_zone_height * wh
148	    };
149	    let seconds = |target: Point, to: Point| {
150	        MOVE_MIN.max((to.0 - target.0).hypot(to.1 - target.1) / (tuning.speed * ww))
151	    };
152	    let go = |keys: &mut Vec<FramingKey>, start: Ticks, end: Ticks, from: Point, to: Point| {
153	        if start > keys.last().expect("the first key").t {
154	            keys.push(frame.key(start, from, Curve::Linear));
155	        }
156	        keys.push(frame.key(end, to, Curve::EaseInOut));
157	    };
158	    for (i, p) in points.iter().enumerate() {
159	        let t = p.t;
160	        let running = last_end.is_some_and(|end| t < end);
161	        // The next click from here whose arrival is still to be made, and
162	        // its planned start (VR-50 (e)).
163	        let next_click = (i.max(handled)..points.len()).find(|&j| points[j].click);
164	        let mut pending: Option<Ticks> = None;
165	        if let Some(j) = next_click.filter(|&j| outside(target, desired[j])) {
166	            let end = snap_to_frame(points[j].t, fps);
167	            let length = (seconds(target, desired[j]) * TIMESCALE as f64).round() as Ticks;
168	            let planned = end.saturating_sub(length).max(last_end.unwrap_or(0));
169	            if end <= duration && !running && t >= planned {
170	                let start = snap_to_frame(t, fps);
171	                if start < end {
172	                    go(&mut keys, start, end, target, desired[j]);
173	                    target = desired[j];
174	                    last_end = Some(end);
175	                    handled = j + 1;
176	                    continue;
177	                }
178	                // Cannot last a frame: dropped; the click is any point.
179	                handled = j + 1;
180	            } else if end <= duration {
181	                pending = Some(planned);
182	            } else {
183	                handled = j + 1;
184	            }
185	        }
186	        if i >= handled && p.click {
187	            handled = i + 1;
188	        }
189	        // VR-50 (f): any other point.
190	        if running || p.typing || !outside(target, desired[i]) {
191	            continue;
192	        }
193	        let in_window =
194	            (raw[i].0 - target.0).abs() <= ww / 2.0 && (raw[i].1 - target.1).abs() <= wh / 2.0;
195	        if last_end.is_some_and(|end| t < end + MOVE_SPACING) && in_window {
196	            continue;
197	        }
198	        let Some((start, end)) = span(t, seconds(target, desired[i]), duration, fps) else {
199	            continue;
200	        };
201	        if pending.is_some_and(|planned| end > planned) {
202	            continue;
203	        }
204	        go(&mut keys, start, end, target, desired[i]);
205	        target = desired[i];
206	        last_end = Some(end);
207	    }
208	    FramingPath {
209	        keys,
210	        shows_fit: false,
211	        cuts: Vec::new(),
212	    }
213	}
