1	//! A framing written as an edit (road map "creator-jobs" VR2a2 and VR2b1,
2	//! spec §11 VR-25…VR-27): `keep`'s rescale and the blurred backdrop behind
3	//! a `fit` span; the path itself is composed into the clip by
4	//! `reframe_compose.rs`. Pure: each answers a new project and
5	//! `edit_reframe.rs`'s op decides, checks and finishes.
6	//!
7	//! **`keep`** (VR-26, VR-27 (h)) is `set_canvas`'s rescale rule on the
8	//! clip's base and on every end key among `x`, `y` and `scale` that the end
9	//! names, through `rescale_video` itself.
10	//!
11	//! **The backdrop** (VR-25) is ONE copy of the original clip by
12	//! `add_blurred_background`'s builder, spanning the whole clip, because the
13	//! eases into and out of `fit` need it as much as the span itself. It goes
14	//! on the named track when that track can take it — unlocked, not a matte,
15	//! no clip intersecting the clip's span (touching is allowed) — and on a new
16	//! back-most track otherwise, so the op never refuses for a busy track. It
17	//! keeps the original's actions that name `speed`, each end narrowed to
18	//! `speed`, so a ramped clip's copy reads the same frames (VR-27 (i)).
19	
20	use serde_json::{Map, Value};
21	
22	use crate::edit_canvas::rescale_video;
23	use crate::model::{Action, Clip, Project, VideoProps};
24	
25	impl Project {
26	    /// `keep` (VR-26, VR-27 (h)): `set_canvas`'s rescale rule on the clip's
27	    /// base and on each `x`, `y` and `scale` an action's end names, from a
28	    /// `from` canvas to the current one.
29	    pub(crate) fn kept(&self, clip: u32, from: (u32, u32)) -> Project {
30	        let mut next = self.clone();
31	        let (w, h) = (
32	            f64::from(next.canvas.width) / f64::from(from.0),
33	            f64::from(next.canvas.height) / f64::from(from.1),
34	        );
35	        let Some(target) = next.clips.iter_mut().find(|c| c.id == clip) else {
36	            return next;
37	        };
38	        if !(w.is_finite() && h.is_finite()) {
39	            return next;
40	        }
41	        if let Some(video) = target.video.as_mut() {
42	            rescale_video(video, w, h);
43	        }
44	        for action in &mut target.actions {
45	            let Some(Value::Object(end)) = action.end.get_mut("video") else {
46	                continue;
47	            };
48	            let read = |key: &str| end.get(key).and_then(Value::as_f64);
49	            let mut video = VideoProps::default();
50	            video.scale = read("scale").unwrap_or(video.scale);
51	            video.x = read("x").unwrap_or(video.x);
52	            video.y = read("y").unwrap_or(video.y);
53	            rescale_video(&mut video, w, h);
54	            for (key, value) in [("scale", video.scale), ("x", video.x), ("y", video.y)] {
55	                if end.get(key).is_some_and(Value::is_number) {
56	                    end.insert(key.to_string(), Value::from(value));
57	                }
58	            }
59	        }
60	        next
61	    }
62	
63	    /// The backdrop of VR-25: one blurred copy of `original` on `backdrop`
64	    /// when that track can take it, else on a new back-most track (the
65	    /// module doc), with the original's speed actions (VR-27 (i)), their ids
66	    /// after the copy's. The op has refused a nest and a track not behind
67	    /// the clip's before calling, so the `Err` is `blurred_copy`'s own and
68	    /// not reached in practice.
69	    pub(crate) fn with_backdrop(self, original: &Clip, backdrop: u32) -> Result<Project, String> {
70	        let (start, end) = (original.start, original.start + original.duration);
71	        let free = self
72	            .track(backdrop)
73	            .is_some_and(|t| !t.locked && t.matte.is_none())
74	            && !self
75	                .clips
76	                .iter()
77	                .any(|c| c.track == backdrop && c.start < end && c.start + c.duration > start);
78	        let (mut next, track) = if free {
79	            (self, backdrop)
80	        } else {
81	            self.with_back_track()
82	        };
83	        let id = next.allocate_id();
84	        let mut copy = next.blurred_copy(original, id, track)?;
85	        for a in original.actions.iter() {
86	            let Some(speed) = a.end.get("speed") else {
87	                continue;
88	            };
89	            let mut end = Map::new();
90	            end.insert("speed".to_string(), speed.clone());
91	            copy.actions.push(Action {
92	                id: next.allocate_id(),
93	                end: Value::Object(end),
94	                ..a.clone()
95	            });
96	        }
97	        next.clips.push(copy);
98	        Ok(next)
99	    }
100	}
