1	//! A framing composed into a clip that already moves (road map
2	//! "creator-jobs" VR2b1, spec §11 VR-27): `reframe.rs`'s path F written as
3	//! the clip's base and actions AROUND the actions it already carries, and
4	//! `replace`'s strip. Pure; `edit_reframe.rs`'s op decides and finishes.
5	//!
6	//! **Composition** (VR-27 (b)). P(t) is the input clip's evaluated
7	//! placement and F′ the scheduled path; a key `(k, dx, dy)` composes as
8	//! `scale′ = k·s`, `x′ = k·x + dx`, `y′ = k·y + dy`, raw. The base becomes
9	//! F′(0)∘P(0); an action end writes `video.{scale,x,y}` = F′(end)∘P(end)
10	//! when it names any of them (`null` included) or F′ changes across it.
11	//!
12	//! **Cuts first** (VR-27 (d)). A cut piece `[c − frame, c]` meeting an
13	//! action A naming `speed`, or ending past the clip, is CARRIED by A; any
14	//! other A is split at `c − frame` and `c`, each clamped into A, as
15	//! `edit_split.rs` narrows a straddled action (`state_patch`, `narrow_to`):
16	//! the head keeps A's id and curve, the cut piece is `linear`, the tail
17	//! keeps A's end and curve. So a linear A plays unchanged on every key,
18	//! volume included; an eased one is re-eased on each side (counted).
19	//!
20	//! **Then the moves** (VR-27 (c)), against the pieces: a move in no busy
21	//! span is its own action; one that overlaps a span is shifted earlier to
22	//! end at its start, by at most [`SHIFT_MAX`] and never before the
23	//! previous key or span; otherwise the first span's action CARRIES it — F′
24	//! holds to A's start and reaches the move's value at A's end along A's
25	//! curve, later moves inside A chaining into it.
26	//!
27	//! **Ids** (VR-27 (e)) are minted in time order for every new action and
28	//! tail; a clip's actions are written in start order. With no actions this
29	//! is VR2a2's writing to the byte: key 0 the base, one action per change.
30	
31	use std::collections::BTreeSet;
32	
33	use serde_json::{Map, Value};
34	
35	use crate::edit_split::{narrow_to, state_patch};
36	use crate::edit_zoom::{zoom_offset, zoom_scale, ZoomFit, ZoomRegion};
37	use crate::model::{Action, Curve, Project, VideoProps};
38	use crate::reframe::{FramingKey, FramingPath};
39	use crate::time::{Ticks, TIMESCALE};
40	
41	/// The furthest a move is shifted earlier to clear an action: 0.5 s.
42	pub const SHIFT_MAX: Ticks = TIMESCALE / 2;
43	
44	/// What composing did that a person may want told (VR-27 (f)).
45	#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
46	pub struct Composed {
47	    /// Non-linear actions split at a cut.
48	    pub re_eased: usize,
49	    /// Actions across which F′ changes from a carried move or cut.
50	    pub carried: usize,
51	}
52	
53	const PLACEMENT: [&str; 3] = ["scale", "x", "y"];
54	
55	type Value3 = (f64, f64, f64);
56	
57	fn names_placement(end: &Value) -> bool {
58	    end.get("video")
59	        .and_then(Value::as_object)
60	        .is_some_and(|v| PLACEMENT.iter().any(|k| v.contains_key(*k)))
61	}
62	
63	/// F′ as keys, read exactly at a key and eased between (`FramingPath::at`).
64	fn at(keys: &[FramingKey], t: Ticks) -> Value3 {
65	    if let Some(k) = keys.iter().find(|k| k.t == t) {
66	        return (k.scale, k.x, k.y);
67	    }
68	    FramingPath {
69	        keys: keys.to_vec(),
70	        shows_fit: false,
71	        cuts: Vec::new(),
72	    }
73	    .at(t)
74	}
75	
76	/// One action of the written list: an existing one (or a piece of one), or
77	/// a new one, and whether its id is still to mint.
78	struct Piece {
79	    action: Action,
80	    fresh: bool,
81	    /// A speed action or one past the clip's end: never split (VR-27 (d)).
82	    whole: bool,
83	}
84	
85	impl Piece {
86	    /// A new action of F′'s own, its end written by (b).
87	    fn new(start: Ticks, duration: Ticks, curve: Curve) -> Piece {
88	        let end = Value::Object(Map::new());
89	        let action = Action {
90	            id: 0,
91	            start,
92	            duration,
93	            curve,
94	            end,
95	        };
96	        Piece {
97	            action,
98	            fresh: true,
99	            whole: false,
100	        }
101	    }
102	
103	    fn end(&self) -> Ticks {
104	        self.action.start.saturating_add(self.action.duration)
105	    }
106	
107	    /// A busy span meeting `[from, to]` (VR-27 (c)).
108	    fn meets(&self, from: Ticks, to: Ticks) -> bool {
109	        self.action.duration > 0 && self.action.start < to && self.end() > from
110	    }
111	}
112	
113	/// F′ being written, and which piece it is carrying through.
114	struct Schedule {
115	    keys: Vec<FramingKey>,
116	    carrier: Option<usize>,
117	    carriers: BTreeSet<usize>,
118	}
119	
120	impl Schedule {
121	    fn push(&mut self, t: Ticks, v: Value3, curve: Curve) {
122	        let key = FramingKey {
123	            t,
124	            scale: v.0,
125	            x: v.1,
126	            y: v.2,
127	            curve,
128	        };
129	        match self.keys.last_mut() {
130	            Some(last) if last.t >= t => *last = key,
131	            _ => self.keys.push(key),
132	        }
133	    }
134	
135	    fn value(&self) -> Value3 {
136	        let k = self.keys.last().expect("key 0");
137	        (k.scale, k.x, k.y)
138	    }
139	
140	    /// A segment of F (`from` → `to`, reaching `v`) as its own motion.
141	    fn own(&mut self, from: Ticks, to: Ticks, v: Value3, curve: Curve) {
142	        let hold = self.value();
143	        if from > self.keys.last().expect("key 0").t {
144	            self.push(from, hold, Curve::Linear);
145	        }
146	        self.push(to, v, curve);
147	        self.carrier = None;
148	    }
149	
150	    /// A segment carried by piece `i` (VR-27 (c)): hold to its start, reach
151	    /// `v` at its end along its curve; a later one inside it chains.
152	    fn carry(&mut self, i: usize, piece: &Piece, v: Value3) {
153	        if self.carrier != Some(i) {
154	            let hold = self.value();
155	            if piece.action.start > self.keys.last().expect("key 0").t {
156	                self.push(piece.action.start, hold, Curve::Linear);
157	            }
158	        }
159	        self.push(piece.end(), v, piece.action.curve);
160	        self.carrier = Some(i);
161	        self.carriers.insert(i);
162	    }
163	}
164	
165	fn compose(f: Value3, p: Value3) -> Value3 {
166	    (f.0 * p.0, f.0 * p.1 + f.1, f.0 * p.2 + f.2)
167	}
168	
169	/// `end`'s `video.{scale,x,y}` set to `v`, keeping every other key.
170	fn write_placement(end: &mut Value, v: Value3) {
171	    if !end.is_object() {
172	        *end = Value::Object(Map::new());
173	    }
174	    let Value::Object(end) = end else { return };
175	    let video = end
176	        .entry("video")
177	        .or_insert_with(|| Value::Object(Map::new()));
178	    if !video.is_object() {
179	        *video = Value::Object(Map::new());
180	    }
181	    if let Value::Object(video) = video {
182	        for (key, n) in PLACEMENT.iter().zip([v.0, v.1, v.2]) {
183	            video.insert((*key).to_string(), Value::from(n));
184	        }
185	    }
186	}
187	
188	impl Project {
189	    /// VR-27 (g): `clip` with `x`, `y` and `scale` removed from every end's
190	    /// `video` (a group left empty dropped, then an end left `{}`), and its
191	    /// base at the Fit placement of the cropped picture on the canvas.
192	    pub fn replaced(&self, clip: u32) -> Project {
193	        let mut next = self.clone();
194	        let Some(index) = next.clips.iter().position(|c| c.id == clip) else {
195	            return next;
196	        };
197	        let size = next.source_size(&next.clips[index]);
198	        let canvas = (f64::from(next.canvas.width), f64::from(next.canvas.height));
199	        let target = &mut next.clips[index];
200	        target.actions.retain_mut(|a| {
201	            let Value::Object(end) = &mut a.end else {
202	                return true;
203	            };
204	            if let Some(Value::Object(video)) = end.get_mut("video") {
205	                for key in PLACEMENT {
206	                    video.shift_remove(key);
207	                }
208	                if video.is_empty() {
209	                    end.shift_remove("video");
210	                }
211	            }
212	            !end.is_empty()
213	        });
214	        if let Some((mw, mh)) = size {
215	            let mut video = target.video.clone().unwrap_or_default();
216	            let crop = video.crop;
217	            let whole = ZoomRegion {
218	                x: 0.0,
219	                y: 0.0,
220	                width: mw - crop.l - crop.r,
221	                height: mh - crop.t - crop.b,
222	            };
223	            let scale = zoom_scale(canvas, &whole, ZoomFit::Fit, 0.0);
224	            let (x, y) = zoom_offset(&video, &whole, scale);
225	            (video.scale, video.x, video.y) = (scale, x, y);
226	            target.video = Some(video);
227	        }
228	        next
229	    }
230	
231	    /// `clip` with `path` composed into its base and actions (the module
232	    /// doc), and what composing counted.
233	    pub fn composed(&self, clip: u32, path: &FramingPath) -> (Project, Composed) {
234	        let mut next = self.clone();
235	        let (Some(index), Some(first)) = (
236	            next.clips.iter().position(|c| c.id == clip),
237	            path.keys.first(),
238	        ) else {
239	            return (next, Composed::default());
240	        };
241	        let original = self.clips[index].clone();
242	        let base = original.video.clone().unwrap_or_default();
243	        let placement = |t: Ticks| -> Value3 {
244	            let v = if original.actions.is_empty() {
245	                base.clone()
246	            } else {
247	                self.evaluate_clip(&original, t).video
248	            };
249	            (v.scale, v.x, v.y)
250	        };
251	        let mut pieces: Vec<Piece> = original
252	            .actions
253	            .iter()
254	            .map(|a| Piece {
255	                whole: a.end.get("speed").is_some()
256	                    || a.start.saturating_add(a.duration) > original.duration,
257	                action: a.clone(),
258	                fresh: false,
259	            })
260	            .collect();
261	        pieces.sort_by_key(|p| (p.action.start, p.action.id));
262	
263	        // F's segments: (from, to, value, curve, is a cut).
264	        let segments: Vec<(Ticks, Ticks, Value3, Curve, bool)> = path
265	            .keys
266	            .windows(2)
267	            .filter(|w| (w[0].scale, w[0].x, w[0].y) != (w[1].scale, w[1].x, w[1].y))
268	            .map(|w| {
269	                let (a, b) = (&w[0], &w[1]);
270	                (
271	                    a.t,
272	                    b.t,
273	                    (b.scale, b.x, b.y),
274	                    b.curve,
275	                    path.cuts.contains(&b.t),
276	                )
277	            })
278	            .collect();
279	
280	        // (d): every cut splits the action it lands in, first.
281	        let mut re_eased: BTreeSet<u32> = BTreeSet::new();
282	        for &(from, to, _, _, cut) in &segments {
283	            if !cut {
284	                continue;
285	            }
286	            let Some(i) = pieces.iter().position(|p| p.meets(from, to)) else {
287	                continue;
288	            };
289	            if pieces[i].whole {
290	                continue;
291	            }
292	            let a = pieces.remove(i);
293	            if a.action.curve != Curve::Linear {
294	                re_eased.insert(a.action.id);
295	            }
296	            let end_at = |t: Ticks| {
297	                narrow_to(
298	                    &state_patch(&self.evaluate_clip(&original, t)),
299	                    &a.action.end,
300	                    0,
301	                )
302	            };
303	            let (cf, ct) = (from.max(a.action.start), to.min(a.end()));
304	            let mut split = vec![
305	                (a.action.start, cf, a.action.curve, end_at(cf)),
306	                (cf, ct, Curve::Linear, end_at(ct)),
307	                (ct, a.end(), a.action.curve, a.action.end.clone()),
308	            ];
309	            split.retain(|&(s, e, _, _)| e > s);
310	            for (n, (start, end, curve, patch)) in split.into_iter().enumerate() {
311	                // The first written piece keeps A's id (the head, unless
312	                // A starts at the cut piece).
313	                let keeps = n == 0 && !a.fresh;
314	                pieces.push(Piece {
315	                    action: Action {
316	                        id: a.action.id,
317	                        start,
318	                        duration: end - start,
319	                        curve,
320	                        end: patch,
321	                    },
322	                    fresh: !keeps,
323	                    whole: false,
324	                });
325	            }
326	            pieces.sort_by_key(|p| (p.action.start, p.action.id));
327	        }
328	
329	        // (c): F′ in time order against the pieces.
330	        let mut f = Schedule {
331	            keys: vec![*first],
332	            carrier: None,
333	            carriers: BTreeSet::new(),
334	        };
335	        let mut own: Vec<Piece> = Vec::new();
336	        for &(from, to, v, curve, cut) in &segments {
337	            let Some(i) = pieces.iter().position(|p| p.meets(from, to)) else {
338	                f.own(from, to, v, curve);
339	                own.push(Piece::new(from, to - from, curve));
340	                continue;
341	            };
342	            let span = &pieces[i];
343	            let start = span.action.start;
344	            // A split cut piece (clamped into its action) is its own segment.
345	            if cut && !span.whole && start >= from && span.end() <= to {
346	                f.own(start, span.end(), v, curve);
347	                continue;
348	            }
349	            let shifted = start - (to - from);
350	            let previous = pieces
351	                .iter()
352	                .map(Piece::end)
353	                .filter(|&e| e <= start)
354	                .max()
355	                .unwrap_or(0)
356	                .max(f.keys.last().expect("key 0").t);
357	            if !cut && f.carrier != Some(i) && to - start <= SHIFT_MAX && shifted >= previous {
358	                f.own(shifted, start, v, curve);
359	                own.push(Piece::new(shifted, to - from, curve));
360	                continue;
361	            }
362	            f.carry(i, &pieces[i], v);
363	        }
364	
365	        // (b): the base and every end.
366	        let keys = f.keys;
367	        let mut carried = 0;
368	        for (i, piece) in pieces.iter_mut().enumerate() {
369	            let (s, e) = (piece.action.start, piece.end());
370	            let changes = at(&keys, s) != at(&keys, e);
371	            if changes && f.carriers.contains(&i) {
372	                carried += 1;
373	            }
374	            if changes || names_placement(&piece.action.end) {
375	                write_placement(&mut piece.action.end, compose(at(&keys, e), placement(e)));
376	            }
377	        }
378	        for piece in &mut own {
379	            let e = piece.end();
380	            write_placement(&mut piece.action.end, compose(at(&keys, e), placement(e)));
381	        }
382	        pieces.extend(own);
383	        // (e): fresh ids in time order, then the list in start order.
384	        pieces.sort_by_key(|p| p.action.start);
385	        for piece in pieces.iter_mut().filter(|p| p.fresh) {
386	            piece.action.id = next.allocate_id();
387	        }
388	        let (scale, x, y) = compose(at(&keys, 0), (base.scale, base.x, base.y));
389	        let target = &mut next.clips[index];
390	        target.video = Some(VideoProps {
391	            scale,
392	            x,
393	            y,
394	            ..base
395	        });
396	        target.actions = pieces.into_iter().map(|p| p.action).collect();
397	        let re_eased = re_eased.len();
398	        (next, Composed { re_eased, carried })
399	    }
400	}
