1	//! The framing path's keys (road map "creator-jobs" VR2a1 and VR2a2, spec
2	//! §11 VR-23, VR-24): what the chosen subject per sample becomes as keys of
3	//! F. VR-23's moves — the median-filtered subject point, the dead zone, the
4	//! speed, the spacing — moved here whole from `reframe.rs`, which keeps the
5	//! frames, the composition and the mapping into clip time; VR-24 adds what
6	//! a real recording needs beyond them:
7	//!
8	//! - **a hard cut at each shot change** — a one-frame `linear` segment
9	//!   ending exactly on the first canvas frame that shows the new shot, onto
10	//!   the new shot's subject's median over its first second;
11	//! - **loss** — a subject gone is held [`LOSS_HOLD`], then another subject is
12	//!   followed, or the framing eases over [`EMPTY_EASE`] to the `where_empty`
13	//!   state and the path goes EMPTY;
14	//! - **return** — from EMPTY once a subject has been seen for
15	//!   [`RETURN_SEEN`];
16	//! - **two people** framed together when both boxes, widened by
17	//!   [`PAIR_WIDEN`], fit the window.
18	//!
19	//! No move or ease ends after the frame before a cut, and a cut counts as a
20	//! move's end for VR-23's spacing. Every key is on the canvas's grid and the
21	//! keys are strictly increasing.
22	
23	use crate::actions::ease;
24	use crate::model::Curve;
25	use crate::reframe::{
26	    Frame, FramingKey, FramingPath, FramingRequest, FramingTuning, Point, WhereEmpty,
27	};
28	pub use crate::reframe_tracks::LOSS_HOLD;
29	use crate::reframe_tracks::{median, Chosen, SubjectBox, SubjectKind};
30	use crate::time::{
31	    one_frame, snap_down_to_frame, snap_to_frame, snap_up_to_frame, Fps, Ticks, TIMESCALE,
32	};
33	
34	/// The ease to `where_empty` after a loss: 0.8 s.
35	pub const EMPTY_EASE: Ticks = TIMESCALE * 4 / 5;
36	/// How long a subject must be seen at every sample before the framing
37	/// returns to it from EMPTY: 0.6 s.
38	pub const RETURN_SEEN: Ticks = TIMESCALE * 3 / 5;
39	/// A cut places the new shot on its subject's median over this: 1 s.
40	pub const CUT_MEDIAN: Ticks = TIMESCALE;
41	/// Each of two people's boxes is widened by this about its centre before
42	/// their union is tested against the window.
43	pub const PAIR_WIDEN: f64 = 1.15;
44	
45	/// The subject point's median reads ±0.5 s.
46	const MEDIAN_SPAN: Ticks = TIMESCALE / 2;
47	/// The shortest move: 0.4 s.
48	pub(crate) const MOVE_MIN: f64 = 0.4;
49	/// No move within 0.5 s of the last one's end…
50	pub(crate) const MOVE_SPACING: Ticks = TIMESCALE / 2;
51	
52	impl FramingPath {
53	    /// (scale, x, y) at clip tick `t`: the segment ending at key i eases with
54	    /// key i's curve (`actions::ease`); before the first key its value, after
55	    /// the last its value.
56	    pub fn at(&self, t: Ticks) -> (f64, f64, f64) {
57	        let value = |k: &FramingKey| (k.scale, k.x, k.y);
58	        let Some(first) = self.keys.first() else {
59	            return (1.0, 0.0, 0.0);
60	        };
61	        let Some(i) = self.keys.iter().position(|k| k.t >= t) else {
62	            return value(self.keys.last().expect("not empty"));
63	        };
64	        if i == 0 {
65	            return value(first);
66	        }
67	        let (a, b) = (&self.keys[i - 1], &self.keys[i]);
68	        let e = ease(b.curve, (t - a.t) as f64 / (b.t - a.t) as f64);
69	        (
70	            a.scale + (b.scale - a.scale) * e,
71	            a.x + (b.x - a.x) * e,
72	            a.y + (b.y - a.y) * e,
73	        )
74	    }
75	
76	    /// Keys whose (scale, x, y) differ from the previous key's.
77	    pub fn moves(&self) -> usize {
78	        self.keys
79	            .windows(2)
80	            .filter(|w| (w[0].scale, w[0].x, w[0].y) != (w[1].scale, w[1].x, w[1].y))
81	            .count()
82	    }
83	}
84	
85	/// What the framing holds: a window centred on a source-canvas point, or
86	/// the whole picture fitted.
87	#[derive(Debug, Clone, Copy, PartialEq)]
88	enum At {
89	    Window(Point),
90	    Fit,
91	}
92	
93	/// The keys as they are written, and the state they leave.
94	struct Writer<'a> {
95	    frame: &'a Frame,
96	    keys: Vec<FramingKey>,
97	    current: At,
98	    shows_fit: bool,
99	    last_end: Option<Ticks>,
100	}
101	
102	impl Writer<'_> {
103	    fn key(&self, t: Ticks, at: At, curve: Curve) -> FramingKey {
104	        match at {
105	            At::Window(wc) => self.frame.key(t, wc, curve),
106	            At::Fit => self.frame.fit_key(t, curve),
107	        }
108	    }
109	
110	    /// A hold key at `start` (unless the last key is there already) and the
111	    /// key `to` at `end` with `curve`.
112	    fn go(&mut self, start: Ticks, end: Ticks, to: At, curve: Curve) {
113	        if start > self.keys.last().expect("the first key").t {
114	            self.keys.push(self.key(start, self.current, Curve::Linear));
115	        }
116	        self.keys.push(self.key(end, to, curve));
117	        self.shows_fit |= to == At::Fit;
118	        self.current = to;
119	        self.last_end = Some(end);
120	    }
121	
122	    fn running(&self, t: Ticks) -> bool {
123	        self.last_end.is_some_and(|end| t < end)
124	    }
125	}
126	
127	/// The subject point and offset of a chosen sample (VR-22), its pair's
128	/// union standing in when both widened boxes fit the window (VR-24 (g)).
129	fn point_of(frame: &Frame, c: &Chosen, headroom: f64) -> Option<(SubjectKind, Point, Point)> {
130	    let (kind, b) = (c.kind?, c.subject?);
131	    let widened = |b: &SubjectBox| {
132	        let (cx, cy) = (b.x + b.w / 2.0, b.y + b.h / 2.0);
133	        let (w, h) = (b.w * PAIR_WIDEN, b.h * PAIR_WIDEN);
134	        (cx - w / 2.0, cy - h / 2.0, cx + w / 2.0, cy + h / 2.0)
135	    };
136	    let pair = c.second.and_then(|other| {
137	        let (a, o) = (widened(&b), widened(&other));
138	        let (x0, y0) = (a.0.min(o.0), a.1.min(o.1));
139	        let (x1, y1) = (a.2.max(o.2), a.3.max(o.3));
140	        let (p0, p1) = (frame.point(c.t, x0, y0), frame.point(c.t, x1, y1));
141	        let fits = p1.0 - p0.0 <= frame.window.0 && p1.1 - p0.1 <= frame.window.1;
142	        fits.then_some(SubjectBox {
143	            x: x0,
144	            y: y0,
145	            w: x1 - x0,
146	            h: y1 - y0,
147	            c: b.c,
148	            mouth: None,
149	        })
150	    });
151	    let (p, offset) = frame.subject(c.t, kind, &pair.unwrap_or(b), headroom);
152	    Some((kind, p, offset))
153	}
154	
155	/// The keys of one clip's path (spec §11 VR-23, VR-24): `chosen` one per
156	/// sample in clip ticks, `shots` the cuts in clip ticks (`Round::Up`).
157	pub(crate) fn write_keys(
158	    frame: &Frame,
159	    chosen: &[Chosen],
160	    shots: &[Ticks],
161	    duration: Ticks,
162	    fps: Fps,
163	    request: &FramingRequest,
164	    tuning: &FramingTuning,
165	) -> FramingPath {
166	    let shot = |t: Ticks| shots.partition_point(|&c| c <= t);
167	    let (ww, wh) = frame.window;
168	    let one = one_frame(fps);
169	    // Each kept cut: its shot's clip tick and its key time `c`, the first
170	    // canvas frame that shows the new shot (VR-24 (a)).
171	    let mut cuts: Vec<(Ticks, Ticks)> = shots
172	        .iter()
173	        .map(|&s| (s, snap_up_to_frame(s, fps)))
174	        .filter(|&(_, c)| c > one && c < duration)
175	        .collect();
176	    cuts.dedup_by_key(|&mut (_, c)| c);
177	    let empty_state = match request.where_empty {
178	        WhereEmpty::Center => At::Window(frame.centre()),
179	        WhereEmpty::Fit => At::Fit,
180	    };
181	
182	    // Each chosen sample's kind, subject point and offset (VR-22, VR-24 (g)).
183	    let points: Vec<Option<(SubjectKind, Point, Point)>> = chosen
184	        .iter()
185	        .map(|c| point_of(frame, c, tuning.headroom))
186	        .collect();
187	    // The median over ±0.5 s of the same kind in the same shot, then the
188	    // desired window centre, clamped (VR-23).
189	    let filtered: Vec<Option<(Point, Point)>> = (0..chosen.len())
190	        .map(|i| {
191	            let (kind, _, offset) = points[i]?;
192	            let t = chosen[i].t;
193	            let lo = chosen.partition_point(|q| q.t < t - MEDIAN_SPAN);
194	            let hi = chosen.partition_point(|q| q.t <= t + MEDIAN_SPAN);
195	            let near: Vec<Point> = (lo..hi)
196	                .filter_map(|j| points[j].filter(|q| q.0 == kind).map(|q| (j, q.1)))
197	                .filter(|&(j, _)| shot(chosen[j].t) == shot(t))
198	                .map(|(_, p)| p)
199	                .collect();
200	            let mut xs: Vec<f64> = near.iter().map(|p| p.0).collect();
201	            let mut ys: Vec<f64> = near.iter().map(|p| p.1).collect();
202	            let fp = (median(&mut xs), median(&mut ys));
203	            Some((fp, frame.clamp((fp.0 + offset.0, fp.1 + offset.1))))
204	        })
205	        .collect();
206	
207	    // The first key (VR-24 (f)): the first chosen sample's desired centre
208	    // when one is chosen within `LOSS_HOLD` in the first shot, else EMPTY.
209	    let first_cut = cuts.first().map_or(Ticks::MAX, |&(s, _)| s);
210	    let first = (0..chosen.len()).find(|&i| filtered[i].is_some());
211	    let (start_at, mut following) = match first {
212	        Some(i) if chosen[i].t < LOSS_HOLD && chosen[i].t < first_cut => (
213	            At::Window(filtered[i].expect("chosen").1),
214	            chosen[i].identity,
215	        ),
216	        _ => (empty_state, None),
217	    };
218	    let mut empty = start_at == empty_state && following.is_none();
219	    let mut w = Writer {
220	        frame,
221	        keys: Vec::new(),
222	        current: start_at,
223	        shows_fit: start_at == At::Fit,
224	        last_end: None,
225	    };
226	    w.keys.push(w.key(0, start_at, Curve::Linear));
227	    let mut cut_keys: Vec<Ticks> = Vec::new();
228	
229	    let mut loss: Option<Ticks> = None;
230	    let mut seen: Option<Ticks> = None;
231	    let mut next = 0usize;
232	    // The frame before a cut's, and the latest a move or an ease may end:
233	    // the frame before the next cut.
234	    let before = |c: Ticks| snap_down_to_frame(c - 1, fps);
235	    let limit = |next: usize| cuts.get(next).map_or(duration, |&(_, c)| before(c));
236	    let mut i = 0usize;
237	    while i <= chosen.len() {
